__NUXT_JSONP__("/jp/havevisa", (function(a){return {data:[{details:{slug:"jp",pageTitle:"日本からの申込で、現在有効なビザがある方の手続き | Mentor Language Institute",pageDescription:a,title:"日本からの申込で、現在有効なビザがある方の手続き",image:"\u002Fimages\u002Fhavevisa\u002Fattraction.png",category:[{title:a,content:["⁻日本（海外）からの申込み\u003Cbr \u002F\u003E⁻アメリカへの滞在歴があり、学生ビザをすでに持っている\u003Cbr \u002F\u003E⁻前回通われていた学校のプログラムを終了してから5ヵ月以上経過していない\u003Cbr \u002F\u003E※5ヵ月以上経過されている方はビザを再取得する必要があります。"]},{title:"手続き手順",image:"\u002Fimages\u002Fhavevisa\u002Fmli-design-apply-short-jp.jpg",ordered_content:["お申し込み","必要書類の提出","I-20の受領","渡米"],content:["現在有効なビザをお持ちの場合は新たにビザ申請をする必要はありません。有効なビザとI-20をもって渡米、入国審査を受ける形になります。","お申込みは授業をスタートする\u003Cstrong\u003E2ヵ月前までに。\u003C\u002Fstrong\u003E手続きは現在のステータスによってとても複雑になるケースがあります。お申込み後、まずはスタッフまで手順を確認して頂くことをお勧めします。"]},{title:"キャンセル規定",content:["お申し込み時に発生する入学金$150はお手続き開始後はいかなる理由があっても\u003Cbr \u002F\u003E返金できませんのであらかじめご了承ください。ただし、\u003Cbr \u002F\u003E滞在先が満室のため受け入れができない、など当校が事由の場合は、その限りではありません。"]},{title:"お申し込み後の手続きの進め方について",image:"\u002Fimages\u002Fhavevisa\u002Fmli-short-jp.jpg",content:["お申し込み後はiMLIと言う当校独自の申し込みシステムにより手続きを進めて参ります。\u003Cbr \u002F\u003E手続き方法はiMLIに記載され、ひとつひとつ順を追って進めていく事が可能です。"],types:[{title:"お申し込みはこちらから",content:["米国ビザに関する情報の入力\u003Cbr \u002F\u003E手続きに関する質問のやりとりも","以下、フォームボタンよりお申込みください。"]}]}],btn_label:"オンライン申込フォームへ",admission:{link:"\u002Fjp\u002Fadmission",content:["※お申込みの際はクレジットカードをご用意ください。"]},dir:"\u002Fhavevisa",path:"\u002Fhavevisa\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:29.452Z",updatedAt:"2025-05-26T12:06:27.776Z"}}],fetch:{},mutations:void 0}}("日本（海外）からの申込で、現在有効なビザがある")));